import { useEffect, useState } from "react";
import { Bar, Pie } from "react-chartjs-2";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from "chart.js";

ChartJS.register(CategoryScale, LinearScale, BarElement, ArcElement, Tooltip, Legend);

export default function Reports() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    fetch("http://127.0.0.1:8000/api/orders/")
      .then(res => res.json())
      .then(setOrders)
      .catch(console.error);
  }, []);

  // ---------- DAILY SALES ----------
  const dailyMap = {};

  orders.forEach(o => {
    if (!o.created_at) return;

    const day = new Date(o.created_at).toLocaleDateString();
    dailyMap[day] = (dailyMap[day] || 0) + o.total;
  });

  const dailyLabels = Object.keys(dailyMap);
  const dailyValues = Object.values(dailyMap);

  const barData = {
    labels: dailyLabels,
    datasets: [
      {
        label: "Daily Sales (₹)",
        data: dailyValues,
        backgroundColor: "rgba(54, 162, 235, 0.7)",
      },
    ],
  };

  // ---------- TOTAL REVENUE ----------
  const totalRevenue = orders.reduce((sum, o) => sum + o.total, 0);

  const pieData = {
    labels: ["Revenue"],
    datasets: [
      {
        data: [totalRevenue],
        backgroundColor: ["#4caf50"],
      },
    ],
  };

  return (
    <div>
      <h3>Sales Reports</h3>

      <h4>Total Revenue: ₹{totalRevenue}</h4>

      <div style={{ width: "400px", marginBottom: "40px" }}>
        <Pie data={pieData} />
      </div>

      <div style={{ width: "600px" }}>
        <Bar data={barData} />
      </div>
    </div>
  );
}
